{
  "summary": "The paper introduces PelviNeXt, a modality-agnostic hybrid architecture for pelvic imaging, combining dense feature extraction, hierarchical CBAM, multi-scale fusion, and talking-heads self-attention. It addresses the lack of reliable datasets for pelvic imaging by auditing and deduplicating the PCOSGen dataset and achieving state-of-the-art results on both PCOSGen and PXR150 datasets. The study highlights the potential of a single architecture for pelvic imaging across modalities in under-researched areas of women's health.",
  "items": {
    "chk_problem": {
      "value": "Women's health is under-researched, with a lack of public, well-annotated benchmark data for pelvic pathologies like PCOS and pelvic fractures.",
      "paper_quote": "Women’s health remains substantially under-resourced in medical imaging research, with pelvic pathologies such as polycystic ovary syndrome (PCOS) and pelvic fracture both suffering from a scarcity of public, well-annotated benchmark data despite their clinical importance."
    },
    "chk_method": {
      "value": "PelviNeXt, a modality-agnostic hybrid architecture combining dense convolutional feature extraction, hierarchical CBAM, multi-scale fusion, and talking-heads self-attention.",
      "paper_quote": "We introduce PelviNeXt, a modality-agnostic hybrid architecture combining a dense convolutional feature extractor, hierarchical channel-spatial attention (H-CBAM), a multi-scale fusion module (MSFM), and talking-heads multi-head self-attention (TH-MHSA), applied without modification to both pelvic ultrasound and X-ray inputs."
    },
    "chk_data": {
      "value": "PCOSGen (deduplicated to 225 images) and PXR150 (150 images).",
      "paper_quote": "The original pool of 4,668 images reduces to 225 (63 Normal, 162 Abnormal), a 95.2% reduction. The deduplicated dataset is publicly released (see Data Availability)."
    },
    "chk_setup": {
      "value": "Models trained with AdamW optimizer, batch size 16, 30 epochs, 5-fold cross-validation, and data augmentation.",
      "paper_quote": "All models are trained from scratch using AdamW (lr = 1×10−4 , cosine annealing), batch size 16, for 30 epochs, under 5-fold stratified cross-validation with augmentation applied only to training folds."
    },
    "chk_primary_result": {
      "value": "PelviNeXt achieved 92.00% accuracy (±1.60) and 0.9051 AUROC (±0.0156) on PCOSGen; 87.33% accuracy (±2.45) and 0.8920 AUROC (±0.0288) on PXR150.",
      "paper_quote": "PelviNeXt achieves the highest performance across all five metrics, with a mean accuracy of 92.00% (±1.60) and AUROC of 0.9051 (±0.0156)... PelviNeXt achieves the highest accuracy (87.33%, ±2.45), recall (89.00%, ±5.71), specificity (87.00%, ±3.92), and AUROC (0.8920, ±0.0288) among all methods..."
    },
    "chk_secondary_result": {
      "value": "PelviNeXt showed the narrowest confidence intervals across most metrics, indicating stable performance in low-data regimes.",
      "paper_quote": "PelviNeXt also shows the narrowest CIs across most metrics: specificity varies by only ±2.99 percentage points for PelviNeXt versus ±12.59 for ViT-B/16, suggesting more stable performance in this low-data regime."
    },
    "chk_baseline": {
      "value": "Compared against ViT-B/16, ResNet-101, DenseNet-169, and prior state-of-the-art methods like Patch Ensemble.",
      "paper_quote": "PelviNeXt achieves the highest accuracy (87.33%, ±2.45), recall (89.00%, ±5.71), specificity (87.00%, ±3.92), and AUROC (0.8920, ±0.0288) among all methods, exceeding the strongest prior result, Patch Ensemble [2] (84.00% accuracy, 87.00% recall, 82.00% specificity, 0.8700 AUROC), across every reported metric."
    },
    "chk_conclusion": {
      "value": "PelviNeXt is a reliable, modality-agnostic architecture for pelvic imaging, achieving state-of-the-art results and addressing data scarcity in women's health.",
      "paper_quote": "These results take a step toward reliable, modality-agnostic computer-assisted tools for under-researched areas of women’s pelvic health."
    },
    "chk_limitation": {
      "value": "Small dataset sizes for both PCOSGen and PXR150 limit statistical power and generalizability.",
      "paper_quote": "A limitation of this work is the small size of both datasets: the deduplicated PCOS dataset contains 225 images and PXR150 contains 150 images, which limits statistical power despite 5-fold CV with 95% CIs."
    }
  }
}
